// Pega os dados do item anterior (que veio do "Obter Tarefa")
const item = $input.item.json;

const nomeCliente = item.name ? item.name.trim() : "Cliente não informado";
const customFields = item.custom_fields || [];

function formataData(timestamp) {
  if (!timestamp || isNaN(timestamp)) return "Não informado";
  const data = new Date(Number(timestamp));
  return data.toLocaleDateString('pt-BR');
}

function nomeOpcao(field) {
  const v = field.value;
  if (v === undefined || v === null || v === '') return "Não informado";
  const opcoes = (field.type_config && field.type_config.options) || [];
  const op = opcoes.find(o => o.orderindex === v || o.id === v);
  return op ? op.name : String(v);
}

let dadosForm = {
  servico: "Não informado",
  categoriaPortfolio: "Não informado",
  complexidade: "Não informado",
  nomeEmpresa: "Não informado",
  porteEmpresa: "Não informado",
  ramoAtividade: "Não informado",
  faturamento: "Não informado",
  objetivoProjeto: "Não informado",
  contextoEmpresa: "Não informado",
  problema: "Não informado",
  combinados: "Não informado",
  resultadosChave: "Não informado",
  indicadoresCliente: "Não informado",
  entregasEsperadas: "Não informado",
  foraEscopo: "Não informado",
  ferramentasSistemas: "Não informado",
  inicioPrevisto: "Não informado",
  prazoCliente: "Não informado",
  orcamento: "Não informado",
  responsavelComercial: "Não informado",
  prazoAprovacao: "Não informado"
};

let responsavelCustom = null;

customFields.forEach(field => {
  const nome = field.name ? field.name.trim().toLowerCase() : "";
  let valor = field.value !== undefined && field.value !== null ? field.value : (field.text_value || "Não informado");

  if (field.type === 'drop_down') {
    valor = nomeOpcao(field);
  } else if (typeof valor === 'string') {
    valor = valor.trim();
  }

  if (nome.includes("faturamento")) {
    dadosForm.faturamento = field.type === 'drop_down' ? nomeOpcao(field) : valor;
  }
  else if (nome.includes("serviço")) {
    dadosForm.servico = valor;
  }
  else if (nome.includes("categoria") || nome.includes("portifólio") || nome.includes("portfolio")) {
    dadosForm.categoriaPortfolio = valor;
  }
  else if (nome.includes("complexidade")) {
    dadosForm.complexidade = valor;
  }
  else if (nome.includes("empresa") && !nome.includes("porte") && !nome.includes("contexto") && !nome.includes("faturamento")) {
    dadosForm.nomeEmpresa = valor;
  }
  else if (nome.includes("contexto")) {
    dadosForm.contextoEmpresa = valor;
  }
  else if (nome.includes("porte")) {
    dadosForm.porteEmpresa = valor;
  }
  else if (nome.includes("ramo") || nome.includes("atividade")) {
    dadosForm.ramoAtividade = valor;
  }
  else if (nome.includes("objetivo")) {
    dadosForm.objetivoProjeto = valor;
  }
  else if (nome.includes("problema")) {
    dadosForm.problema = valor;
  }
  else if (nome.includes("combinado")) {
    dadosForm.combinados = valor;
  }
  else if (nome.includes("resultado") || nome.includes("chave")) {
    dadosForm.resultadosChave = valor;
  }
  else if (nome.includes("indicador")) {
    dadosForm.indicadoresCliente = valor;
  }
  else if (nome.includes("entrega")) {
    dadosForm.entregasEsperadas = valor;
  }
  else if (nome.includes("fora") || nome.includes("não está incluído")) {
    dadosForm.foraEscopo = valor;
  }
  else if (nome.includes("ferramenta") || nome.includes("sistema")) {
    dadosForm.ferramentasSistemas = valor;
  }
  else if (nome.includes("início") || nome.includes("inicio")) {
    dadosForm.inicioPrevisto = formataData(valor);
  }
  else if (nome.includes("prazo máximo") || nome.includes("prazo desejado")) {
    dadosForm.prazoCliente = formataData(valor);
  }
  else if (nome.includes("orçamento") || nome.includes("faixa")) {
    dadosForm.orcamento = valor;
  }
  else if (nome.includes("aprovação")) {
    dadosForm.prazoAprovacao = formataData(valor);
  }
  else if (nome.includes("responsável comercial") || nome.includes("responsavel comercial")) {
    if (Array.isArray(field.value) && field.value.length > 0 && field.value[0].username) {
      responsavelCustom = field.value[0].username;
    } else if (typeof field.value === 'string') {
      responsavelCustom = field.value;
    }
  }
});

if (responsavelCustom) {
  dadosForm.responsavelComercial = String(responsavelCustom).trim();
} else if (item.creator && item.creator.username) {
  dadosForm.responsavelComercial = String(item.creator.username).trim();
} else {
  dadosForm.responsavelComercial = "Não informado";
}

function limpaTexto(txt) {
  if (!txt) return "Não informado";
  return String(txt).replace(/\n{2,}/g, '\n').trim();
}

const promptIa = [
  "Você é um gerente de projetos sênior e especialista em planejamento estratégico de uma Empresa Júnior de consultoria empresarial.",
  `Com base nas informações detalhadas do briefing abaixo, crie uma EAP (Estrutura Analítica do Projeto) altamente customizada, viável, respeitando a complexidade e o porte da empresa, alinhada aos combinados e que caiba entre o Início Previsto e o Prazo Máximo do Cliente, além de uma minuta de escopo e precificação.`,
  "",
  "--- CONTEXTO DO CLIENTE E PROJETO ---",
  `- Nome do Contato / Lead: ${limpaTexto(nomeCliente)}`,
  `- Nome da Empresa: ${limpaTexto(dadosForm.nomeEmpresa)}`,
  `- Porte da Empresa: ${limpaTexto(dadosForm.porteEmpresa)}`,
  `- Ramo de Atividade: ${limpaTexto(dadosForm.ramoAtividade)}`,
  `- Faturamento Estimado: ${limpaTexto(dadosForm.faturamento)}`,
  "",
  "--- PARÂMETROS DO SERVIÇO ---",
  `- Tipo de Serviço: ${limpaTexto(dadosForm.servico)}`,
  `- Categoria do Portfólio: ${limpaTexto(dadosForm.categoriaPortfolio)}`,
  `- Complexidade Estimada: ${limpaTexto(dadosForm.complexidade)}`,
  `- Objetivo do Projeto: ${limpaTexto(dadosForm.objetivoProjeto)}`,
  "",
  "--- NOVOS DETALHES DO BRIEFING ---",
  `- Contexto da Empresa: ${limpaTexto(dadosForm.contextoEmpresa)}`,
  `- Problema a Resolver: ${limpaTexto(dadosForm.problema)}`,
  `- Combinados: ${limpaTexto(dadosForm.combinados)}`,
  `- Resultados-chave Esperados: ${limpaTexto(dadosForm.resultadosChave)}`,
  `- Indicadores que o Cliente já Acompanha: ${limpaTexto(dadosForm.indicadoresCliente)}`,
  `- Entregas Esperadas: ${limpaTexto(dadosForm.entregasEsperadas)}`,
  `- O que NÃO está incluído no Escopo: ${limpaTexto(dadosForm.foraEscopo)}`,
  `- Ferramentas e Sistemas do Cliente: ${limpaTexto(dadosForm.ferramentasSistemas)}`,
  "",
  "--- PRAZOS E ORÇAMENTO ---",
  `- Início Previsto: ${limpaTexto(dadosForm.inicioPrevisto)}`,
  `- Prazo Máximo do Cliente: ${limpaTexto(dadosForm.prazoCliente)}`,
  `- Faixa de Orçamento: ${limpaTexto(dadosForm.orcamento)}`,
  `- Prazo Limite para Aprovação da EAP: ${limpaTexto(dadosForm.prazoAprovacao)}`,
  `- Responsável Comercial: ${limpaTexto(dadosForm.responsavelComercial)}`,
  "",
  "--- DIRETRIZES DE SAÍDA E REGRAS ---",
  'Retorne a resposta estritamente em formato JSON válido, contendo:',
  '1. "resumo_executivo": texto descritivo detalhado.',
  '2. "fases": lista de fases com "nome_fase", "descricao", "duracao_dias" e "tarefas" (cada tarefa com "nome_tarefa", "descricao", "dias_uteis", "reunioes", "horas").',
  '3. "precificacao": objeto contendo:',
  '   - "custo_total_projeto" (número): valor total do projeto calculado considerando as horas totais, complexidade e a faixa de orçamento informada.',
  '   - "valor_hora_sugerido" (número): valor da hora técnica adequado ao porte e faturamento da empresa.',
  '   - "margem_lucro" (texto ou número): margem aplicada.',
  '   - "condicoes_pagamento" (texto): condições sugeridas alinhadas ao orçamento.',
  '   - "justificativa" (texto): explicação detalhada da composição do preço baseada no faturamento, complexidade e esforço.',
  '',
  'REGRAS OBRIGATÓRIAS:',
  '- Considere apenas dias úteis (sem finais de semana/feriados).',
  '- Carga horária média de até 3h por dia útil por tarefa.',
  '- Não altere os números definidos em "Combinados".'
].join("\n");

return {
  json: {
    nomeCliente,
    dadosForm,
    promptIa
  }
};

const inputData = $input.item.json;
const aiResponse = inputData.mergedResponse || (inputData.message && inputData.message.content) || inputData.text || '';

let jsonString = aiResponse.trim();
if (jsonString.indexOf('```json') === 0) {
  jsonString = jsonString.substring(7);
} else if (jsonString.indexOf('```') === 0) {
  jsonString = jsonString.substring(3);
}
if (jsonString.lastIndexOf('```') !== -1) {
  jsonString = jsonString.substring(0, jsonString.lastIndexOf('```'));
}
jsonString = jsonString.trim();

const eap = JSON.parse(jsonString);

function adicionaDiasUteis(dataBase, dias) {
  let d = new Date(dataBase);
  let diasRestantes = Math.max(0, dias - 1);
  while (diasRestantes > 0) {
    d.setDate(d.getDate() + 1);
    let diaSemana = d.getDay();
    if (diaSemana !== 0 && diaSemana !== 6) {
      diasRestantes--;
    }
  }
  return d;
}

function proximoDiaUtil(dataBase) {
  let d = new Date(dataBase);
  d.setDate(d.getDate() + 1);
  while (d.getDay() === 0 || d.getDay() === 6) {
    d.setDate(d.getDate() + 1);
  }
  return d;
}

function formataDataBR(date) {
  const dia = String(date.getDate()).padStart(2, '0');
  const mes = String(date.getMonth() + 1).padStart(2, '0');
  const ano = date.getFullYear();
  return dia + '/' + mes + '/' + ano;
}

let dataCorrente = new Date(2026, 9, 26); // 26/10/2026
let linhasEap = [];
let linhasCronograma = [];
let totalHorasGeral = 0;
let totalDiasGeral = 0;

if (eap.fases && Array.isArray(eap.fases)) {
  for (let indexFase = 0; indexFase < eap.fases.length; indexFase++) {
    const fase = eap.fases[indexFase];
    const numFase = indexFase + 1;

    let totalHorasFase = 0;
    let totalReunioesFase = 0;
    let totalDiasFase = 0;

    if (fase.tarefas && Array.isArray(fase.tarefas)) {
      fase.tarefas.forEach(t => { 
        totalHorasFase += (t.horas || 0); 
        totalReunioesFase += (t.reunioes || 0);
        const diasT = t.dias_uteis || Math.ceil((t.horas || 3) / 2.5);
        totalDiasFase += diasT;
      });
    }

    totalHorasGeral += totalHorasFase;
    totalDiasGeral += totalDiasFase;

    const duracaoFase = fase.duracao_dias || totalDiasFase;
    const dataFimFase = adicionaDiasUteis(dataCorrente, duracaoFase);

    linhasEap.push({
      'ETAPA': String(numFase),
      'STATUS': 'Não iniciada',
      'NOME DA ETAPA': fase.nome_fase || ('Fase ' + numFase),
      'DESCRIÇÃO': fase.descricao || '',
      'DIAS ÚTEIS': duracaoFase,
      'REUNIÕES': totalReunioesFase,
      'HORAS': totalHorasFase
    });

    linhasCronograma.push({
      'ETAPA': String(numFase),
      'INÍCIO': formataDataBR(dataCorrente),
      'FIM': formataDataBR(dataFimFase)
    });

    let dataInicioTarefa = new Date(dataCorrente);

    if (fase.tarefas && Array.isArray(fase.tarefas)) {
      for (let indexTarefa = 0; indexTarefa < fase.tarefas.length; indexTarefa++) {
        const tarefa = fase.tarefas[indexTarefa];
        const numTarefa = indexTarefa + 1;
        const codigoEtapa = numFase + '.' + numTarefa;
        const diasUteisTarefa = tarefa.dias_uteis || Math.ceil((tarefa.horas || 3) / 2.5);
        const dataFimTarefa = adicionaDiasUteis(dataInicioTarefa, diasUteisTarefa);

        linhasEap.push({
          'ETAPA': codigoEtapa,
          'STATUS': tarefa.status || '',
          'NOME DA ETAPA': tarefa.nome_tarefa || '',
          'DESCRIÇÃO': tarefa.descricao || '',
          'DIAS ÚTEIS': diasUteisTarefa,
          'REUNIÕES': tarefa.reunioes || 0,
          'HORAS': tarefa.horas || 0
        });

        linhasCronograma.push({
          'ETAPA': codigoEtapa,
          'INÍCIO': formataDataBR(dataInicioTarefa),
          'FIM': formataDataBR(dataFimTarefa)
        });

        dataInicioTarefa = proximoDiaUtil(dataFimTarefa);
      }
    }

    dataCorrente = proximoDiaUtil(dataFimFase);
  }
}

// ==========================================
// CÁLCULO EXATO DA PRECIFICAÇÃO CONFORME PLANILHA
// ==========================================
// Pega a complexidade direto do formulário ou da resposta da IA
const complexidadeProjeto = (inputData.dadosForm && inputData.dadosForm.complexidade) || 
                            (eap.precificacao && eap.precificacao.complexidade) || 
                            "Média";

// Parâmetros base da EJ
const custoFixoPorHora = 52.525473; 
const custoVariavelProjeto = 0.0; 
const impostoServicos = 0.05;
const taxaFejece = 0.04;
const auxilioTransporte = 0.03;
const auxilioAlimentacao = 0.01;
const investimentosReservas = 0.05;

// Lucro líquido conforme complexidade (Média = 7%, Alta = 12%, Baixa = 2%)
let lucroLiquido = 0.02; 
const compLower = String(complexidadeProjeto).toLowerCase();
if (compLower.includes('médi') || compLower.includes('medi')) {
  lucroLiquido = 0.07;
} else if (compLower.includes('alt')) {
  lucroLiquido = 0.12;
}

const custoFixoProjeto = totalHorasGeral * custoFixoPorHora;
const custoTotalProjeto = custoFixoProjeto + custoVariavelProjeto;

// Soma dos percentuais para o Markup
const somaPercentuais = impostoServicos + taxaFejece + auxilioTransporte + auxilioAlimentacao + lucroLiquido + investimentosReservas;
const markup = 1 / (1 - somaPercentuais);
const valorTotalProjeto = custoTotalProjeto * markup;

// Linhas mapeadas exatamente para preencher a coluna "VALOR" correspondente a cada fator
let linhasPrecificacao = [
  { 'FATOR': 'Horas do projeto', 'VALOR': totalHorasGeral },
  { 'FATOR': 'Custo fixo por hora', 'VALOR': Number(custoFixoPorHora.toFixed(4)) },
  { 'FATOR': 'Custo fixo do projeto', 'VALOR': Number(custoFixoProjeto.toFixed(2)) },
  { 'FATOR': 'Custos variáveis', 'VALOR': Number(custoVariavelProjeto.toFixed(2)) },
  { 'FATOR': 'Custo total do projeto', 'VALOR': Number(custoTotalProjeto.toFixed(2)) },
  { 'FATOR': 'Complexidade', 'VALOR': complexidadeProjeto },
  { 'FATOR': 'Impostos e taxas', 'VALOR': Number((impostoServicos + taxaFejece).toFixed(2)) },
  { 'FATOR': 'Auxílios da equipe', 'VALOR': Number((auxilioTransporte + auxilioAlimentacao).toFixed(2)) },
  { 'FATOR': 'Lucro líquido desejado', 'VALOR': Number(lucroLiquido.toFixed(2)) },
  { 'FATOR': 'Investimentos e reservas', 'VALOR': Number(investimentosReservas.toFixed(2)) },
  { 'FATOR': 'Markup', 'VALOR': Number(markup.toFixed(4)) },
  { 'FATOR': 'VALOR TOTAL DO PROJETO', 'VALOR': Number(valorTotalProjeto.toFixed(2)) }
];

return [{
  json: {
    eap: linhasEap,
    cronograma: linhasCronograma,
    precificacao: linhasPrecificacao
  }
}];
